            inputs.theta.val.handle = uicontrol(inputs.handle,'Style','edit','String',inputs.theta.val.string,'Position',inputs.theta.val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            inputs.phi.val.handle = uicontrol(inputs.handle,'Style','edit','String',inputs.phi.val.string,'Position',inputs.phi.val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            %
            inputs.bt.reset.handle  = uicontrol(inputs.handle,'Style','pushbutton','String',inputs.bt.reset.string,'Position',inputs.bt.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',inputs.bt.reset.callback);
            inputs.zp.reset.handle  = uicontrol(inputs.handle,'Style','pushbutton','String',inputs.zp.reset.string,'Position',inputs.zp.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',inputs.zp.reset.callback);
            inputs.theta.reset.handle  = uicontrol(inputs.handle,'Style','pushbutton','String',inputs.theta.reset.string,'Position',inputs.theta.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',inputs.phi.reset.callback);
            inputs.phi.reset.handle  = uicontrol(inputs.handle,'Style','pushbutton','String',inputs.phi.reset.string,'Position',inputs.phi.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',inputs.phi.reset.callback);
            %
%             targets..title.handle = uicontrol(targets.handle,'Style','text','String',targets..title.string,'Position',targets..title.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.rho.title.handle = uicontrol(targets.handle,'Style','text','String',targets.rho.title.string,'Position',targets.rho.title.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.theta.title.handle = uicontrol(targets.handle,'Style','text','String',targets.theta.title.string,'Position',targets.theta.title.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.npar.title.handle = uicontrol(targets.handle,'Style','text','String',targets.npar.title.string,'Position',targets.npar.title.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            %
%             targets..val.handle = uicontrol(targets.handle,'Style','edit','String',targets..title.string,'Position',targets..val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.rho.val.handle = uicontrol(targets.handle,'Style','edit','String',targets.rho.val.string,'Position',targets.rho.val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.theta.val.handle = uicontrol(targets.handle,'Style','edit','String',targets.theta.val.string,'Position',targets.theta.val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            targets.npar.val.handle = uicontrol(targets.handle,'Style','edit','String',targets.npar.val.string,'Position',targets.npar.val.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'HorizontalAlignment','left');
            %
%             targets..reset.handle  = uicontrol(targets.handle,'Style','pushbutton','String',targets..reset.string,'Position',targets..reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',targets..reset.callback);
            targets.rho.reset.handle  = uicontrol(targets.handle,'Style','pushbutton','String',targets.rho.reset.string,'Position',targets.rho.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',targets.rho.reset.callback);
            targets.theta.reset.handle  = uicontrol(targets.handle,'Style','pushbutton','String',targets.theta.reset.string,'Position',targets.theta.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',targets.npar.reset.callback);
            targets.npar.reset.handle  = uicontrol(targets.handle,'Style','pushbutton','String',targets.npar.reset.string,'Position',targets.npar.reset.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',targets.npar.reset.callback);
            %
            run.handle  = uicontrol(controls.handle,'Style','pushbutton','String',run.string,'Position',run.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',run.callback);
%             guess.handle  = uicontrol(controls.handle,'Style','pushbutton','String',guess.string,'Position',guess.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',guess.callback);
            optim.handle  = uicontrol(controls.handle,'Style','pushbutton','String',optim.string,'Position',optim.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',optim.callback);
            finish.handle  = uicontrol(controls.handle,'Style','pushbutton','String',finish.string,'Position',finish.position,'FontName',style.fontname,'FontUnits','pixels','FontSize',style.fontsize,'Callback',finish.callback);
