                   str2double(inputs.zp.val.string),...
                   str2double(inputs.theta.val.string),...
                   str2double(inputs.phi.val.string)];
        %
        ntargets = [str2double(targets.rho.val.string),...
                    str2double(targets.theta.val.string),...
                    str2double(targets.npar.val.string)];
        %
        if ~any(isnan(ninputs)),% all inputs defined or calculated
            set(finish.handle,'Enable','on');
        else
            set(finish.handle,'Enable','off');
        end
        %
        uiwait;
        %
    end
    %
    return
    %
    wave = wave_solver_yp(dkepath,wavestruct,[]);
    %
    
    
    %
    if opt_info,
        delete(inputs.handle);
        delete(targets.handle);
        delete(controls.handle);
        delete(info.handle);
    end

    
    
    %
    optim.iray = 2;% with one ray and one reflection only : (1) reflected X, (2) reflected O
    optim.tol = 1e-2;% tolerance on target (in m)
    optim.nitmax = 10;%
    %
    %Zp = NaN;%0.18;%0.14;%0.12;%NaN;%Plasma vertical position (m)
    Te0 = NaN;%3;%central temperature, in keV
    ne19_0 = NaN;%2;%central density, in 10^19 m-3
    %
    % Path parameters
    %
    id_dkepath = '';%For all paths used by DKE solver
    path_dkepath = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
    %
    % Equilibrium parameters
    %
    id_equil = [basestr,'_',shotnum,'_',shotime];%For plasma equilibrium
    path_equil = [shotnum,'/'];%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
    %
    wavepath = [shotnum,'/WAVE/'];
    %
    % Wave parameters
    %
    waveparam.mmode = 1;%-1;%cold plasma mode [1] : (-1) m (1) p, p is the slow mode when kperp > 0 (ex : LH slow wave)
    %
    %Option parameter for FLR effects and cross-comparison between old FP code: 
    %	- (0): all FLR effects
    %	- (1): small FLR effects and 1/vpar dependence
    %	- (2): small FLR effects and no 1/vpar dependence and old grid technique for DQL calculations (Karney, Shoucri) (see rfdiff_dke_jd)
    %
    waveparam.opt_rf = 0;
    %
    waveparam.dsmin = 0.001;%minimum size for ray fragments
    %
    waveparam.nd = 1;%3;%Number of transverse distance positions for beamlets
    waveparam.nchi = 1;%6;%1;%4;%Number of angular positions for beamlets
    %
    waveparam.n_rf_list = [1  2  3];
    waveparam.ns = 1;%ray smoothing parameter
    %
    % Global parameters for the vectorial magnetic equilibrium
    %
    % Equilibrium parameters for the ray-tracing
    %
    fitparam.nharm = 32;%8;%Number of harmonics in the magnetic equilibrium interpolation (less than ntheta_equil/2)
    %
    % Global parameters for the ray-tracing
    %
    rayparam.tol = 1e-8;%1e-12;%when tolerance is increased (less accurate calculation of D=0), tfinal must be increased accordingly
    rayparam.reflection = -1;%0;%1:Enforce wave reflection at plasma boundary, 0: the code calculates itself if the ray must leave of not the plasma
    %
    % Display parameters
    %
    C3POdisplay.ray = 0;
    %
    % C3PO computing parameters
    %
    C3POparam.clustermode.main_C3PO_jd.scheduler.mode = 0;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
    %
    % -------------------------------------------------------------------------
    %
    % Load structures
    %
    if ~isnan(Zp),
        id_equil = [id_equil,'_Zp_',num2str(1000*Zp)];
    end
    %
    [dkepath,equil] = load_structures_yp('dkepath',id_dkepath,path_dkepath,'equil',id_equil,path_equil);
    %
    if ~isnan(Te0),
        equil.pTe = equil.pTe*Te0/equil.pTe(1);
        equil.pzTi = equil.pzTi*Te0/equil.pTe(1);
        equil.id = [equil.id,'_Te0_',num2str(Te0)];
    end
    if ~isnan(ne19_0),
        equil.pne = equil.pne*ne19_0*1e19/equil.pne(1);
        equil.pzni = equil.pzni*ne19_0*1e19/equil.pne(1);
        equil.id = [equil.id,'_ne0_',num2str(ne19_0)];
    end   
    %
    % update default values with inputs
    %
    C3POparam_EC = load('C3POPARAM_EC.mat','fitparam','rayparam','C3POparam','C3POdisplay','waveparam');
    %
    waveparam = conc_struct_jd(C3POparam_EC.waveparam,waveparam);
    fitparam = conc_struct_jd(C3POparam_EC.fitparam,fitparam);
    rayparam = conc_struct_jd(C3POparam_EC.rayparam,rayparam);
    C3POdisplay = conc_struct_jd(C3POparam_EC.C3POdisplay,C3POdisplay);
    C3POparam = conc_struct_jd(C3POparam_EC.C3POparam,C3POparam);
    %
    equil_fit = fitequil_yp(equil,fitparam.mode_equil,fitparam.method,fitparam.ngridresample,fitparam.nharm);
    %
    % Build angles, launch and rayinit structures
    %
    angles = struct;
    %
    angles.freq = freq*1e9;%Hz
    angles.P0 = P0*1e3;%W
    %
    angles.l_opt = l_opt;
    %
    [Xopt,delta] = fminsearch(@(X) calc_delta_jd(X,angles,dkepath,equil,equil_fit,waveparam,fitparam,rayparam,C3POdisplay,C3POparam,optim.iray),[theta,phi],...
        optimset('TolFun',optim.tol,'MaxIter',optim.nitmax,'PlotFcns',@optimplotfval));
    %
    [~,wave] = calc_delta_jd(Xopt,angles,dkepath,equil,equil_fit,waveparam,fitparam,rayparam,C3POdisplay,C3POparam,optim.iray);
    tau_end = wave.rays{optim.iray}.stau(end);
    abs_end = 100*(1 - exp(-tau_end));
    %
    if ~isempty(d_opt),
        diary(d_opt);
    end
    disp('---------------------')
    disp(['time  : ',shotime,' s'])
    disp(['Zp    : ',num2str(equil.Zp),' m'])
    disp(' ');
    disp(['theta : ',num2str(Xopt(1)),'°'])
    disp(['phi   : ',num2str(Xopt(2)),'°'])
    disp(['delta : ',num2str(delta),' m'])
    disp(['tau   : ',num2str(tau_end)])
    disp(['fabs  : ',num2str(abs_end),' %'])
    %
    if ~isempty(d_opt),
        diary('off');
    end
    %
    optim_res.Zp = Zp;
    optim_res.theta = Xopt(1);
    optim_res.phi = Xopt(2);
    optim_res.delta = delta;
    optim_res.tau = tau_end;
    optim_res.fabs = abs_end;
    %
end
%    
function [delta,wave] = calc_delta_jd(thetaphi,angles,dkepath,equil,equil_fit,waveparam,fitparam,rayparam,C3POdisplay,C3POparam,iray)
    %
    theta = thetaphi(1);
    phi = thetaphi(2);
    %
    angles.theta = theta*pi/180;%rad
    angles.phi = phi*pi/180;%rad
    %
    angles = imake_angles_TCV_jd('','',angles.l_opt,1,angles);
    %
    launch = imake_launch_angles_TCV_jd(angles);
    launch.type = 'EC';
    launch.ns = 1000;
    launch.method = 'cubic';
    launch.id = 'optim';
    %
    rayinit = main_rayinit_launch_jd(equil,launch);
    %
    id_rayinit = ['C3PO_',launch.id];
    %
    rayinit.id = id_rayinit;
    rayinit.type = launch.type;
    %
    % -------------------------------------------------------------------------
    %
    % C3P0 ray tracing
    %
    wave = main_C3PO_jd(dkepath,id_rayinit,equil,equil_fit,rayinit,waveparam,fitparam,rayparam,C3POdisplay,C3POparam);
    %
    delta = delta_wave_jd(-phi,theta,wave.rays{iray},equil.Rp,equil.Zp);
    %
end

